44	    using SmemCopyAtom = Copy_Atom<SM75_U32x4_LDSM_N, elem_type>;
45	    using SmemCopyAtomTransposed = Copy_Atom<SM75_U16x8_LDSM_T, elem_type>;
46	#else
47	    using SmemCopyAtom = Copy_Atom<DefaultCopy, elem_type>;
48	    using SmemCopyAtomTransposed = Copy_Atom<DefaultCopy, elem_type>;
