52	// If Share_Q_K_smem is true, that forces Is_Q_in_regs to be true
53	template<int kHeadDim_, int kBlockM_, int kBlockN_, int kNWarps_, bool Is_Q_in_regs_=false, bool Share_Q_K_smem_=false, int quant_mode_=0, int num_bits_=4, int group_size_=128, typename elem_type=cutlass::half_t,
54	         typename Base=Flash_kernel_traits<kHeadDim_, kBlockM_, kBlockN_, kNWarps_, elem_type> >
55	struct Flash_fwd_kernel_traits : public Base {
56	    static constexpr bool Has_cp_async = Base::Has_cp_async;
57	
58	    // TODO
59	    using Element = typename Base::Element;
60	    using ElementKVPack = cute::uint16_t;
61	    using ElementAccum = typename Base::ElementAccum;
62	    using index_t      = typename Base::index_t;
