65	    using SmemCopyAtomTransposed = typename Base::SmemCopyAtomTransposed;
66	
67	    static constexpr bool Share_Q_K_smem = Share_Q_K_smem_;
68	    static constexpr bool Is_Q_in_regs   = Is_Q_in_regs_ || Share_Q_K_smem;
69	
70	    static constexpr int quant_mode = quant_mode_;
71	    static constexpr int group_size = group_size_;
72	    static constexpr int num_bits   = num_bits_;
73	    static constexpr int pack_num   = 16 / num_bits;
74	
75	    static constexpr int residual_block_size = num_bits == 4 ? 128 : 256;
76	
77	    // The number of threads.
78	    static constexpr int kNWarps    = kNWarps_;
79	    static constexpr int kNThreads  = kNWarps * 32;
80	
81	    static constexpr int kBlockM            = kBlockM_;
82	    static constexpr int kBlockN            = kBlockN_;
83	    static constexpr int kBlockN_pack       = num_bits   == 4 ? 128 : 256;
84	    static constexpr int kBlockN_residual   = kBlockN_pack;
85	    static constexpr int kBlockP            = quant_mode == 1 ? kBlockN / pack_num : kBlockN;
86	    static constexpr int kBlockP_new_pack   = quant_mode == 1 ? kBlockN_pack / pack_num : kBlockN_pack;
87	    static constexpr int kBlockK_params     = quant_mode == 1 ? kBlockN / group_size : kBlockN;
88	    static constexpr int kBlockK_params_new = quant_mode == 1 ? kBlockN_pack / group_size : kBlockN_pack;
89	    static constexpr int kHeadDim           = kHeadDim_;
90	    static constexpr int kHeadDim_pack      = kHeadDim / pack_num; 
91	    static constexpr int kHeadDim_k         = quant_mode == 1 ? kHeadDim : kHeadDim_pack;
92	    static constexpr int kHeadDim_k_params  = quant_mode == 1 ? kHeadDim : kHeadDim / group_size;
93	    static constexpr int kHeadDim_v_params  = kHeadDim / group_size;
94	
95	    static constexpr int k_pack_div         = quant_mode == 1 ? pack_num : 1;
96	    // static constexpr int k_params_div       = quant_mode == 1 ? group_size : 1;
97	
98	    static_assert(kHeadDim % 32 == 0);
99	    static constexpr int kBlockKSmem = kHeadDim % 64 == 0 ? 64 : 32;
100	    static constexpr int kBlockKGmem = kHeadDim % 128 == 0 ? 128 : (kHeadDim % 64 == 0 ? 64 : 32);
101	    static constexpr int kSwizzle    = kBlockKSmem == 32 ? 2 : 3;
102	
103	    static constexpr int tile_paramsk_g   = kBlockN / 32 * (kBlockN / group_size); // TODO: check
104	    static constexpr int tile_paramsk_g_r = kBlockN_residual / 32 * (kBlockN_residual / group_size); // TODO: check
105	    static constexpr int tile_paramsk_j   = kBlockN / group_size;
106	    static constexpr int tile_paramsk_m   = kBlockN / kBlockN_pack;
107	    static constexpr int tile_paramsk_k   = kHeadDim / 16;
108	    static constexpr int tile_paramsv_k   = kBlockN / 16;    
109	    static constexpr int tile_paramsv_k_r = kBlockN_residual / 16;
110	
111	    static constexpr int num_params = kBlockN_pack / group_size; // TODO: check 128
112	
113	    //
114	    // Tiled MMA
115	    //
