76	template<typename Kernel_traits, bool Is_causal>
77	void run_flash_splitkv_fwd(Flash_fwd_params &params, cudaStream_t stream) {
78	    static_assert(!Kernel_traits::Is_Q_in_regs, "SplitKV implementation does not support Is_Q_in_regs");
79	    static_assert(!Kernel_traits::Share_Q_K_smem, "SplitKV implementation does not support Share_Q_K_smem");
80	    constexpr size_t smem_size     = Kernel_traits::kSmemSize;
81	    constexpr size_t smem_size_res = Kernel_traits::kSmemSize_res;
82	    const int num_m_block = (params.seqlen_q + Kernel_traits::kBlockM - 1) / Kernel_traits::kBlockM; 
83	    const int num_splits_ = params.num_splits - 1;
84	    
85	    dim3 grid_res(num_m_block, params.b, params.h);
86	    dim3 grid(num_m_block, num_splits_, params.b * params.h);
87	    const bool is_even_MN = params.cu_seqlens_q == nullptr && params.cu_seqlens_k == nullptr && params.seqlen_k % Kernel_traits::kBlockN == 0 && params.seqlen_q % Kernel_traits::kBlockM == 0;
88	    const bool is_even_K = params.d == Kernel_traits::kHeadDim;
89	
90	    auto kernel_res = &flash_fwd_residual_kernel<Kernel_traits, Is_causal, false, false, false, true, false, /*Split*/true, false, false>;
91	    if (smem_size_res >= 48 * 1024) {
92	        C10_CUDA_CHECK(cudaFuncSetAttribute(
93	            kernel_res, cudaFuncAttributeMaxDynamicSharedMemorySize, smem_size_res));
94	    }
95	    kernel_res<<<grid_res, Kernel_traits::kNThreads, smem_size_res, stream>>>(params);
96	    C10_CUDA_KERNEL_LAUNCH_CHECK();
97	
98	    auto kernel = &flash_fwd_splitkv_kernel<Kernel_traits, Is_causal, false, false, false, true, false, /*Split*/true, false, false>;
99	    if (smem_size >= 48 * 1024) {
100	        C10_CUDA_CHECK(cudaFuncSetAttribute(
101	            kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, smem_size));
102	    }
103	    kernel<<<grid, Kernel_traits::kNThreads, smem_size, stream>>>(params);
104	    C10_CUDA_KERNEL_LAUNCH_CHECK();
105	
106	    if (params.num_splits > 1) {
107	        constexpr static int kBlockM = Kernel_traits::kHeadDim % 128 == 0 ? 4 : (Kernel_traits::kHeadDim % 64 == 0 ? 8 : 16);
108	        dim3 grid_combine((params.b * params.h * params.seqlen_q + kBlockM - 1) / kBlockM);
109	        EVENK_SWITCH(is_even_K, IsEvenKConst, [&] {
110	            if (params.num_splits <= 2) {
111	                flash_fwd_splitkv_combine_kernel<Kernel_traits, kBlockM, 1, IsEvenKConst><<<grid_combine, Kernel_traits::kNThreads, 0, stream>>>(params);
112	            } else if (params.num_splits <= 4) {
113	                flash_fwd_splitkv_combine_kernel<Kernel_traits, kBlockM, 2, IsEvenKConst><<<grid_combine, Kernel_traits::kNThreads, 0, stream>>>(params);
114	            } else if (params.num_splits <= 8) {
115	                flash_fwd_splitkv_combine_kernel<Kernel_traits, kBlockM, 3, IsEvenKConst><<<grid_combine, Kernel_traits::kNThreads, 0, stream>>>(params);
116	            } else if (params.num_splits <= 16) {
117	                flash_fwd_splitkv_combine_kernel<Kernel_traits, kBlockM, 4, IsEvenKConst><<<grid_combine, Kernel_traits::kNThreads, 0, stream>>>(params);
118	            } else if (params.num_splits <= 32) {
119	                flash_fwd_splitkv_combine_kernel<Kernel_traits, kBlockM, 5, IsEvenKConst><<<grid_combine, Kernel_traits::kNThreads, 0, stream>>>(params);
120	            } else if (params.num_splits <= 64) {
121	                flash_fwd_splitkv_combine_kernel<Kernel_traits, kBlockM, 6, IsEvenKConst><<<grid_combine, Kernel_traits::kNThreads, 0, stream>>>(params);
122	            } else if (params.num_splits <= 128) {
123	                flash_fwd_splitkv_combine_kernel<Kernel_traits, kBlockM, 7, IsEvenKConst><<<grid_combine, Kernel_traits::kNThreads, 0, stream>>>(params);
124	            }
125	            C10_CUDA_KERNEL_LAUNCH_CHECK();
126	        });
127	    }
